#include "livestock.hh"

extern "C" u32 func_08063E8C(Livestock const * animal);

u32 func_08063E8C(Livestock const * animal)
{
    if (animal->IsSick())
    {
#if defined(REGION_JP)
        return 0x50;
#else
        return 0x58;
#endif
    }

    if (animal->IsUnhappy())
    {
#if defined(REGION_JP)
        return 0x44;
#else
        return 0x48;
#endif
    }

    return 0x38;
}

